      "source_ids": ["context_4d79e8b0335c674e0ef7061b94ee3471", "context_4880e8f2cd6feb858236c20181921f5c"]
    },
    {
      "id": "r4",
      "status": "met",
      "stem_evidence_id": "s4",
      "answer_evidence_id": "e10",
      "explanation": "来源指出乱序时 NextByteExpected 指向第一个缺口起点；答案将 NextByteExpected 定位到第 201 字节即最先缺失区间起点，正确完成两者相对位置的比较判断。",
      "source_ids": ["context_4880e8f2cd6feb858236c20181921f5c"]
    },
    {
      "id": "r5",
      "status": "met",
      "stem_evidence_id": "s7",
      "answer_evidence_id": "e13",
      "explanation": "题干以第 6 条明确排除延迟确认、重传并保证接收缓冲足够大；答案未引入任何未说明的实现细节，仅按给定到达序列判定，符合在有限到达序列范围内作答的要求。",
      "source_ids": ["context_4d79e8b0335c674e0ef7061b94ee3471"]
    }
  ],
